import sys
sys.stdout = open\(sys.stdout.fileno\(\), mode='w', encoding='utf-8', errors='replace'\)
from core.extractor import extract
for fn in ['vulnbox.txt', 'watcher.txt', 'anonymous.txt']:
    raw = open\(f'tests/samples/{fn}', encoding='utf-8', errors='replace'\).read\(\)
    result = extract\(raw\)
    writable_exec_paths = set\(\)
    other_paths = set\(\)
    for f in result['findings']:
        if f['type'] == 'writable_exec_script':
            writable_exec_paths.add\(f['script_path']\)
        elif 'script' in f or 'full_path' in f:
            p = f.get\('script'\) or f.get\('full_path', ''\)
            if p: other_paths.add\(p\)
    print\(f'{fn}: writable_exec={writable_exec_paths} overlap={writable_exec_paths & other_paths}'\)")
